#include <cuda_runtime.h>

#define TILE_SIZE 64
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Block and thread indices
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Each thread computes a 4x4 tile of C
    const int THREAD_TILE_SIZE = 4;

    // Double buffering: two sets of shared memory tiles
    __shared__ float As[2][TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[2][TILE_SIZE][TILE_SIZE];

    // Thread-local registers for accumulating results
    float C_local[THREAD_TILE_SIZE][THREAD_TILE_SIZE] = {{0}};

    // Prefetch the first tile
    int load_phase = 0;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load next tile into the other buffer
        int next_load_phase = 1 - load_phase;

        // Load tile from A and B into shared memory
        #pragma unroll
        for (int i = 0; i < TILE_SIZE; i += blockDim.y) {
            int row = by * TILE_SIZE + ty + i;
            int col = t * TILE_SIZE + tx;

            if (row < N && col < N) {
                As[next_load_phase][ty + i][tx] = A[row * N + col];
            } else {
                As[next_load_phase][ty + i][tx] = 0.0f;
            }
        }

        #pragma unroll
        for (int i = 0; i < TILE_SIZE; i += blockDim.x) {
            int row = t * TILE_SIZE + ty;
            int col = bx * TILE_SIZE + tx + i;

            if (row < N && col < N) {
                Bs[next_load_phase][ty][tx + i] = B[row * N + col];
            } else {
                Bs[next_load_phase][ty][tx + i] = 0.0f;
            }
        }

        __syncthreads();

        // Compute using the current buffer
        for (int k = 0; k < TILE_SIZE; k += UNROLL_FACTOR) {
            // Prefetch next elements
            float4 a_vals[THREAD_TILE_SIZE];
            float4 b_vals[THREAD_TILE_SIZE];

            #pragma unroll
            for (int i = 0; i < THREAD_TILE_SIZE; i++) {
                a_vals[i] = *reinterpret_cast<const float4*>(&As[load_phase][ty * THREAD_TILE_SIZE + i][k]);
